import { forwardRef, useRef } from 'react'
import { m, useScroll, useTransform } from 'motion/react'
import { ArrowRight } from 'lucide-react'
import Reveal from '../ui/Reveal'
import { ButtonLink } from '../ui/Button'
import { usePrefersReducedMotion } from '../../lib/hooks'

/**
 * A framed screenshot of the analyst desk (generated by scripts/screenshots.mjs --product).
 * It sits first in the light zone: the page background turns light while this dark image passes.
 */
const ProductShot = forwardRef<HTMLElement>(function ProductShot(_, ref) {
  const reduced = usePrefersReducedMotion()
  const frameRef = useRef<HTMLDivElement>(null)
  const { scrollYProgress } = useScroll({ target: frameRef, offset: ['start end', 'end start'] })
  const y = useTransform(scrollYProgress, [0, 1], reduced ? [0, 0] : [70, -70])

  return (
    <section ref={ref} aria-labelledby="desk-title" className="relative pt-16 pb-24 sm:pt-24 sm:pb-32">
      <div className="mx-auto max-w-6xl px-4 sm:px-6">
        <div ref={frameRef}>
          <m.figure style={{ y }} className="overflow-hidden rounded-2xl border border-line bg-[#0f1914] shadow-[0_40px_120px_-30px_rgba(7,13,10,0.45)]">
            <div className="flex items-center gap-2 border-b border-white/10 px-4 py-3" aria-hidden="true">
              <span className="size-2.5 rounded-full bg-white/20" />
              <span className="size-2.5 rounded-full bg-white/20" />
              <span className="size-2.5 rounded-full bg-white/20" />
              <span className="ml-3 font-mono text-xs text-white/60">Gaffer · analyst desk</span>
            </div>
            <img
              src={`${import.meta.env.BASE_URL}product/app-desk.jpg`}
              width={1440}
              height={900}
              loading="lazy"
              decoding="async"
              className="block w-full"
              alt="The Gaffer analyst desk: the pitch with White 3-4-3 marked verified, the shape timeline, and the 16:30 alert with its evidence and Approve and Reject buttons."
            />
          </m.figure>
        </div>
        <Reveal className="mx-auto mt-16 max-w-3xl text-center">
          <h2 id="desk-title" className="text-4xl leading-[1.05] font-bold text-text sm:text-6xl">
            One pitch. One timeline. One alert.
          </h2>
          <p className="mt-5 text-lg text-muted sm:text-xl">Everything else waits one click away.</p>
          <ButtonLink to="/app" variant="ghost" size="lg" className="mt-8">
            Open the analyst desk <ArrowRight className="size-4" aria-hidden="true" />
          </ButtonLink>
        </Reveal>
      </div>
    </section>
  )
})

export default ProductShot
